import{z as i,x as s,o as t,c as d,q as r,j as l,D as B,d as A,s as n,S as o,b as a}from"./chunks/framework.C8m1ZpeB.js";const c=JSON.parse('{"title":"从数据到策略","description":"","frontmatter":{"title":"从数据到策略","date":"2026-09-18T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/alt-data-to-strategy.md","filePath":"quant/alt-data-to-strategy.md","lastUpdated":1791413859000}'),C={name:"quant/alt-data-to-strategy.md"};function p(D,E,F,u,h,f){const e=s("Mermaid");return t(),d("div",null,[E[2]||(E[2]=r('<h1 id="从数据到策略" tabindex="-1">从数据到策略 <a class="header-anchor" href="#从数据到策略" aria-label="Permalink to &quot;从数据到策略&quot;">​</a></h1><div class="epigraph"><p>数据与策略之间隔着一段协议：先写清怎样算成功、怎样算失败，再看数据；顺序反过来，回测会替你把任何假设都圆上。</p><footer>—— 据 Bailey and López de Prado, The Deflated Sharpe Ratio, 2014 整理</footer></div><p><a href="/quant/alt-cost-structure">上一课</a>把成本列成全口径：许可、排他、自建、评估、合规，盈亏平衡挂在年化贡献对成本上。本课是工程单元的合拢：把过了质量门禁、算得清成本的数据，变成一条进组合的信号，并配好失败时的退场。单点判据都已立过——<a href="/quant/backtest-overfitting">回测过拟合</a>的折价、<a href="/quant/bailey-dsr">紧缩夏普</a>的 \\(N\\) 调整、<a href="/quant/label-horizon-overlap">标签与持仓期</a>的重叠纪律；缺的是把它们串成顺序并记账的<strong>协议</strong>。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>各判据分散在不同课，实践里「试用一份 vendor 数据」没有统一协议。结果是三件系统性浪费：试得快、上得快、忘得也快——试过多少个表征与数据集没人记，\\(N\\) 事后无从追认，折价算不了；负结果不归档，同一份数据明年换个包装再试一遍，等于对同一个零假设反复开火；判据在看完数据之后才定，「试用成功」被默认为「找到了一个能看的配置」——这是无惩罚的多重检验，不是研究。缺口因此不是新检验，是<strong>顺序与账本</strong>。</p><p><span class="marginnote">「多重检验」就是同一道题反复作答：从 100 个试过的配置里挑最好的那个，它的好成绩很可能只是运气——就像掷 100 次硬币总会出现一段连正面。不记录总共掷了几次，就没法判断这段连正面是本事还是概率。\\(N\\) 记的正是「一共掷了几次」。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>五站流水线，每站有门禁与产出物。第一站假设登记：为什么这份数据有别人尚未交易的信息？写清传导渠道、预期半衰期、以及它可能只是已知因子的再包装的方式——上一课的残差增量判据在这里预注册。第二站试用协议：样本期、基准（增量相对词典、相对已有因子组合）、中性化规格、判据与终止条款，全部在看数据之前签字，终止条款接上一课的「不达标终止权」。第三站构造与对齐：行业与市场中性化，持有期对齐交付时钟与信息半衰期，执行基准用<a href="/quant/arrival-price">到达价</a>，扣费口径在协议里写死。第四站组合接入：增量暴露与<a href="/quant/fz-marginal-contribution">因子边际贡献</a>，容量按<a href="/quant/live-capacity-estimate">容量估计</a>的口径上限管理。第五站生产与台账：特征进<a href="/quant/feature-store-research">特征商店</a>的门禁，试用次数计入 \\(N\\) 台账，负结果连同判据归档进复盘库，可检索。</p><p><span class="marginnote">预注册就像考试前公布评分标准：先写死「达到什么算及格、什么算放弃」，再开卷答题。若允许看完答案再定标准，人人都能「及格」——数据试用同理，判据后置的试用成功率恒为高，但毫无信息量。</span></p>',9)),(t(),l(o,null,{default:B(()=>[n(e,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20H%5B%22%E5%81%87%E8%AE%BE%E7%99%BB%E8%AE%B0%EF%BC%9A%E6%B8%A0%E9%81%93%E4%B8%8E%E5%8D%8A%E8%A1%B0%E6%9C%9F%22%5D%20--%3E%20P%5B%22%E8%AF%95%E7%94%A8%E5%8D%8F%E8%AE%AE%EF%BC%9A%E5%88%A4%E6%8D%AE%E5%85%88%E4%BA%8E%E6%95%B0%E6%8D%AE%22%5D%0A%20%20P%20--%3E%20D%7B%22%E6%89%A3%E8%B4%B9%E5%90%8E%E5%88%A4%E6%8D%AE%E8%BE%BE%E6%A0%87%EF%BC%9F%22%7D%0A%20%20D%20--%3E%7C%E5%90%A6%7C%20ARC%5B%22%E8%B4%9F%E7%BB%93%E6%9E%9C%E4%B8%8E%E5%88%A4%E6%8D%AE%E5%BD%92%E6%A1%A3%22%5D%0A%20%20D%20--%3E%7C%E6%98%AF%7C%20C%5B%22%E6%9E%84%E9%80%A0%E4%B8%8E%E5%AF%B9%E9%BD%90%EF%BC%9A%E4%B8%AD%E6%80%A7%E5%8C%96%E3%80%81%E6%8C%81%E6%9C%89%E6%9C%9F%22%5D%0A%20%20C%20--%3E%20PF%5B%22%E7%BB%84%E5%90%88%E6%8E%A5%E5%85%A5%EF%BC%9A%E8%BE%B9%E9%99%85%E8%B4%A1%E7%8C%AE%E4%B8%8E%E5%AE%B9%E9%87%8F%22%5D%0A%20%20PF%20--%3E%20PR%5B%22%E7%94%9F%E4%BA%A7%EF%BC%9A%E9%97%A8%E7%A6%81%E4%B8%8E%20N%20%E5%8F%B0%E8%B4%A6%22%5D%0A%20%20PR%20--%3E%20MON%7B%22%E8%A1%B0%E5%87%8F%E6%88%96%E8%A6%86%E7%9B%96%E8%B7%8C%E7%A0%B4%EF%BC%9F%22%7D%0A%20%20MON%20--%3E%7C%E6%98%AF%7C%20EXIT%5B%22%E9%80%80%E5%9C%BA%E6%9C%BA%E5%88%B6%E5%90%AF%E5%8A%A8%22%5D%0A%20%20MON%20--%3E%7C%E5%90%A6%7C%20PR%0A"})]),fallback:B(()=>[...E[0]||(E[0]=[A(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=a("h2",{id:"机制",tabindex:"-1"},[A("机制 "),a("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=a("p",null,[A("顺序为什么不可换：折价的分子是试过的次数，\\(N\\) 只能从预注册的账本里来，从事后记忆里来的 \\(N\\) 永远偏小；判据先于模型是本课程一贯口径，在利率与信用案例里收过束（"),a("a",{href:"/quant/rc-case-map"},"利率与信用案例与收束"),A("）。退场机制与进场的判据同源：预注册时写下的半衰期与覆盖下限，就是衰减治理的触发线，信号衰减到判据以下按协议退出，而不是按情绪坚持。不这么做的错法：试用成功即上线、无退场条款——数据的商品化与对手方的涌入会让信息优势单调衰减，没有退场机制的信号最终以滑点的形式把利润还回去。")],-1)),E[5]||(E[5]=a("p",null,[a("span",{class:"marginnote"},"试用结束时应当能答出三个数：试了几个表征与配置（\\(N\\)）、扣费后的紧缩夏普、相对词典或供应商基线的增量 IC。三个数答不出任何一个，就不该转正式采购——这条三问判据把过拟合折价、费用现实与增量要求压进一张便签。")],-1)),E[6]||(E[6]=a("p",null,"同一份数据、两种顺序的结局对比——回答「为什么判据必须先于数据」：",-1)),(t(),l(o,null,{default:B(()=>[n(e,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20A1%5B%22%E9%A2%84%E6%B3%A8%E5%86%8C%EF%BC%9A%E5%85%88%E7%99%BB%E8%AE%B0%E8%A6%81%E8%AF%95%E7%9A%84%E5%81%87%E8%AE%BE%22%5D%20--%3E%20A2%5B%22%E5%88%A4%E6%8D%AE%E4%B8%8E%E7%BB%88%E6%AD%A2%E6%9D%A1%E6%AC%BE%E5%9C%A8%E7%9C%8B%E6%95%B0%E6%8D%AE%E5%89%8D%E7%AD%BE%E5%AD%97%22%5D%0A%20%20A2%20--%3E%20A3%5B%22%E9%80%90%E6%AC%A1%E8%AF%95%E7%94%A8%EF%BC%8C%E6%AC%A1%E6%95%B0%E5%85%A8%E9%83%A8%E8%AE%B0%E8%B4%A6%22%5D%0A%20%20A3%20--%3E%20A4%5B%22%E6%8A%98%E4%BB%B7%E5%8F%AF%E7%AE%97%EF%BC%8C%E7%B4%A7%E7%BC%A9%E5%A4%8F%E6%99%AE%E5%8F%AF%E4%BF%A1%EF%BC%8C%E5%8F%AF%E8%BF%9B%E7%BB%84%E5%90%88%22%5D%0A%20%20B1%5B%22%E4%BA%8B%E5%90%8E%EF%BC%9A%E5%85%88%E7%BF%BB%E6%95%B0%E6%8D%AE%22%5D%20--%3E%20B2%5B%22%E6%8C%91%E5%87%BA%E5%A5%BD%E7%9C%8B%E7%9A%84%E9%85%8D%E7%BD%AE%22%5D%0A%20%20B2%20--%3E%20B3%5B%22%E5%88%A4%E6%8D%AE%E4%BA%8B%E5%90%8E%E8%A1%A5%E5%86%99%EF%BC%8CN%20%E5%87%AD%E8%AE%B0%E5%BF%86%E5%81%8F%E5%B0%8F%22%5D%0A%20%20B3%20--%3E%20B4%5B%22%E6%8A%98%E4%BB%B7%E5%A4%B1%E7%9C%9F%EF%BC%8C%E5%AE%9E%E7%9B%98%E6%8A%8A%E5%88%A9%E6%B6%A6%E8%BF%98%E5%9B%9E%E5%8E%BB%22%5D%0A"})]),fallback:B(()=>[...E[1]||(E[1]=[A(" Loading... ",-1)])]),_:1})),E[7]||(E[7]=r('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>各判据的数学在各自课里已经给出，本课不重推；因子研究的方法论整体归因子深化课程，组合层的优化归组合构建课程，本课只到「信号进组合的门」为止。供应商层面的合同条款归成本结构课；退场之后的知识沉淀与台账治理归策略生命周期治理的口径。预注册不是形式主义：它的产出物（协议文本、\\(N\\) 台账、负结果库）是后续任何复现与审计的原始证据。</p><p><span class="marginnote">负结果库是防止「重复付费」的资产：同一份数据明年换个供应商或换个名字再来时，检索台账 30 秒就能回答「试过，\\(N=17\\)，死因是换手吃光边际」。没有这本账，组织会对同一个零假设反复开火，学费一遍遍地交。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>五站流水线：假设登记、试用协议、构造对齐、组合接入、生产台账，每站有门禁与产出物。</li><li>判据在看数据之前签字；\\(N\\) 只认预注册账本，不认事后记忆。</li><li>负结果连判据归档、可检索，否则同一数据被反复试错且折价无从计算。</li><li>进场判据与退场触发同源，衰减到线即按协议退出。</li><li>出处：Bailey and López de Prado, 2014（紧缩夏普）；Harvey and Liu 关于多重检验的讨论；本课程研究复盘与成本结构各课。</li></ul>',5))])}const q=i(C,[["render",p]]);export{c as __pageData,q as default};
